'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Clock, User } from 'lucide-react';

export default function FacultyWorkloadPage() {
    const [workload, setWorkload] = useState<any[]>([]);

    useEffect(() => { load(); }, []);

    const load = async () => {
        try {
            const res = await api.get<any[]>('/api/institution/faculty-workload');
            if (res.success) setWorkload(res.data);
        } catch { }
    };

    const getUtilColor = (pct: number) => {
        if (pct > 90) return '#DC2626';
        if (pct > 70) return '#F59E0B';
        return '#16A34A';
    };

    return (
        <div>
            <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins', marginBottom: 8 }}>Faculty Workload</h1>
            <p style={{ fontSize: 14, color: '#5a6a72', marginBottom: 24 }}>View teaching load and subject assignments for all faculty</p>

            {/* Summary Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 }}>
                <div className="card" style={{ padding: 20, borderTop: '3px solid #142B34' }}>
                    <div style={{ fontSize: 24, fontWeight: 800, fontFamily: 'Poppins' }}>{workload.length}</div>
                    <div style={{ fontSize: 13, color: '#8a9aa2' }}>Total Faculty</div>
                </div>
                <div className="card" style={{ padding: 20, borderTop: '3px solid #16A34A' }}>
                    <div style={{ fontSize: 24, fontWeight: 800, fontFamily: 'Poppins', color: '#16A34A' }}>
                        {workload.filter(w => w.utilization < 70).length}
                    </div>
                    <div style={{ fontSize: 13, color: '#8a9aa2' }}>Under-loaded</div>
                </div>
                <div className="card" style={{ padding: 20, borderTop: '3px solid #F59E0B' }}>
                    <div style={{ fontSize: 24, fontWeight: 800, fontFamily: 'Poppins', color: '#F59E0B' }}>
                        {workload.filter(w => w.utilization >= 70 && w.utilization <= 90).length}
                    </div>
                    <div style={{ fontSize: 13, color: '#8a9aa2' }}>Optimal</div>
                </div>
                <div className="card" style={{ padding: 20, borderTop: '3px solid #DC2626' }}>
                    <div style={{ fontSize: 24, fontWeight: 800, fontFamily: 'Poppins', color: '#DC2626' }}>
                        {workload.filter(w => w.utilization > 90).length}
                    </div>
                    <div style={{ fontSize: 13, color: '#8a9aa2' }}>Over-loaded</div>
                </div>
            </div>

            {/* Faculty Table */}
            <div className="table-container">
                <table>
                    <thead>
                        <tr>
                            <th>Faculty</th>
                            <th>Email</th>
                            <th>Current / Max Hours</th>
                            <th>Utilization</th>
                            <th>Subjects Assigned</th>
                        </tr>
                    </thead>
                    <tbody>
                        {workload.length === 0 ? (
                            <tr><td colSpan={5} style={{ textAlign: 'center', padding: 32, color: '#8a9aa2' }}>
                                <Clock size={32} style={{ margin: '0 auto 8px', opacity: 0.3, display: 'block' }} />
                                No faculty found. Create faculty via Users page or Bulk Import.
                            </td></tr>
                        ) : workload.map(f => (
                            <tr key={f.id}>
                                <td style={{ fontWeight: 600 }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                                        <div style={{
                                            width: 32, height: 32, borderRadius: 6, background: '#059669',
                                            color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            fontSize: 13, fontWeight: 700,
                                        }}>{f.name?.charAt(0)?.toUpperCase()}</div>
                                        {f.name}
                                    </div>
                                </td>
                                <td style={{ fontSize: 13, color: '#5a6a72' }}>{f.email}</td>
                                <td>
                                    <span style={{ fontWeight: 700, color: '#142B34' }}>{f.current_hours_per_week}</span>
                                    <span style={{ color: '#8a9aa2' }}> / {f.max_hours_per_week} hrs</span>
                                </td>
                                <td>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                        <div style={{
                                            width: 80, height: 8, borderRadius: 4, background: '#e2e6ea', overflow: 'hidden',
                                        }}>
                                            <div style={{
                                                width: `${Math.min(f.utilization, 100)}%`, height: '100%',
                                                background: getUtilColor(f.utilization), borderRadius: 4,
                                                transition: 'width 0.3s',
                                            }} />
                                        </div>
                                        <span style={{ fontSize: 12, fontWeight: 700, color: getUtilColor(f.utilization) }}>
                                            {f.utilization}%
                                        </span>
                                    </div>
                                </td>
                                <td>
                                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4 }}>
                                        {f.assigned_subjects?.length > 0 ? f.assigned_subjects.map((s: any, i: number) => (
                                            <span key={i} className="badge badge-info" style={{ fontSize: 10 }}>
                                                {s.subjects?.code || s.subject_id?.slice(0, 6)}
                                            </span>
                                        )) : (
                                            <span style={{ fontSize: 12, color: '#8a9aa2' }}>None</span>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
